package glitch

import data.glitch_lib

# Insecure protocol patterns (cleartext transmission)
insecure_protocol_patterns := {"http://", "ftp://", "telnet://", "smtp://", "tcp://"}

# Patterns indicating disabled encryption
disabled_encryption_patterns := {"disable", "off", "false", "no", "skip", "ignore", "disabled", "allowed", "prefer", "allow"}

# Patterns indicating enabled encryption (to check for negation)
encryption_keywords := {"ssl", "tls", "https", "encryption", "secure", "encrypted", "transitEncryption", "tlsVersion", "sslPolicy", "sslMode", "requireSsl", "useSsl", "enforceSsl", "secureTransport", "httpsOnly", "enableHttpsTrafficOnly", "requireSecureTransfer", "atRestEncryptionEnabled", "transitEncryptionEnabled", "sslEnabled", "encrypted", "secureTcp"}

# Protocol field names
protocol_fields := {"protocol", "scheme", "url", "endpoint", "address", "source", "destination", "host", "connection", "transport"}

# Insecure protocol values
insecure_protocol_values := {"http", "ftp", "telnet", "smtp", "tcp", "udp", "plaintext", "clear"}

# Weak TLS versions
weak_tls_versions := {"TLSv1.0", "TLSv1.1", "1.0", "1.1"}

# Weak SSL modes
weak_ssl_modes := {"disabled", "disable", "prefer", "allow", "off", "false"}

# Required secure fields that should be present
secure_required_fields := {"tls", "certificate", "sslCertificate", "certificateArn", "certificateAuthority", "trustedCaCert", "clientCertificate", "serverNameIndication", "sni"}

# Check if a string value starts with insecure protocol
is_insecure_protocol_url(value) {
    proto := insecure_protocol_patterns[_]
    startswith(value, proto)
}

# Check if value indicates disabled encryption
is_disabled_encryption(value) {
    lower(value) == disabled_encryption_patterns[_]
}

# Check if attribute name is related to encryption
is_encryption_attribute(name) {
    lower(name) == encryption_keywords[_]
}

# Check if attribute name is a protocol field
is_protocol_field(name) {
    lower(name) == protocol_fields[_]
}

# Check if value is an insecure protocol
is_insecure_protocol(value) {
    lower(value) == insecure_protocol_values[_]
}

# Check if TLS version is weak
is_weak_tls_version(value) {
    upper(value) == weak_tls_versions[_]
}

# Check if SSL mode is weak
is_weak_ssl_mode(value) {
    lower(value) == weak_ssl_modes[_]
}

# Check if a string contains http:// (insecure)
contains_insecure_url(str) {
    contains(lower(str), "http://")
}

# Check if value is false boolean (indicating disabled security)
is_false_bool(node) {
    node.ir_type == "Boolean"
    node.value == false
}

# Check if value is a string representing false/disabled
is_false_string(node) {
    node.ir_type == "String"
    is_disabled_encryption(node.value)
}

# Generic check: attribute that should enable encryption but is set to false/disabled
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check if attribute name indicates encryption setting
    is_encryption_attribute(attr.name)

    # Check if value disables encryption
    is_false_bool(attr.value) or is_false_string(attr.value)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Encryption for data in transit is explicitly disabled. (CWE-319)"
    }
}

# Check for insecure protocol in URL/endpoint fields
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check if it's a protocol/URL field
    is_protocol_field(attr.name)

    # Check for insecure protocol in string value
    attr.value.ir_type == "String"
    is_insecure_protocol(attr.value.value)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Insecure protocol used for data transmission. (CWE-319)"
    }
}

# Check for http:// in any string value
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr.value.ir_type == "String"
    contains_insecure_url(attr.value.value)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - HTTP URL detected, data transmitted in cleartext. (CWE-319)"
    }
}

# Check for weak TLS version
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

